#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {}
    virtual void speak() const {
        cout << name << "：喵～" << endl;
    }
};

class OrangeCat : public Cat {
public:
    OrangeCat(string n) : Cat(n) {}
    void speak() const override {
        cout << name << "：本喵是橘猫，喵喵喵！" << endl;
    }
};

class TabbyCat : public Cat {
public:
    TabbyCat(string n) : Cat(n) {}
    void speak() const override {
        cout << name << "：本喵是狸花猫，喵呜～" << endl;
    }
};

int main() {
    OrangeCat o("小橘");
    TabbyCat t("狸花");
    Cat* cats[2] = { &o, &t };
    for (int i = 0; i < 2; i++) {
        cats[i]->speak();
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {
        cout << "搭猫妈妈那一半：" << name << endl;
    }
    ~Cat() {
        cout << "拆猫妈妈那一半：" << name << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n) : Cat(n) {
        cout << "搭小猫那一半：" << name << endl;
    }
    ~Kitten() {
        cout << "拆小猫那一半：" << name << endl;
    }
};

int main() {
    Cat* p = new Kitten("小橘");
    delete p;
    return 0;
}
